var i=`0588-ashak`;var t=`world-0588`;var o=`AF`;var l=`south-asia`;var a=4;var g=74;var r={en:`Ashak`,ua:`Ашак`};var s={en:`A traditional dish from Afghanistan, centered on all-purpose flour, leek, green onion, plain yogurt. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Афганістан. Основні складники: пшеничне борошно універсальне, цибуля-порей, зелена цибуля, натуральний йогурт. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,410,`g`],[`water`,180,`ml`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`leek`,360,`g`],[`green-onion`,120,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:24,i:[]},{en:`Boil the leek-filled dumplings until the wrappers are tender and the filling is cooked; drain before adding yogurt and mint.`,ua:`Відваріть пельмені з цибулею-пореєм до м’якості тіста й готовності начинки; відцідіть і полийте йогуртом із м’ятою.`,t:[`boiling`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`plain-yogurt`,300,`g`],[`garlic`,3,`clove`],[`mint`,12,`g`]]}];var u={slug:i,id:t,country:`AF`,region:l,servings:4,minutes:74,title:r,text:s,steps:d};export{o as country,u as default,t as id,g as minutes,l as region,a as servings,i as slug,d as steps,s as text,r as title};